using System;using System.IO;using System.Linq;using System.Collections.Generic;using System.Threading.Tasks;using UnityEngine;using UnityEditor;using FireSafety;
public static class CampusPerformance {
static async Task<object> Sample(string label){var samples=new List<float>();double start=Time.realtimeSinceStartupAsDouble;int last=Time.frameCount;while(Time.realtimeSinceStartupAsDouble-start<10){await Task.Delay(8);if(Time.frameCount!=last){last=Time.frameCount;samples.Add(Time.unscaledDeltaTime*1000);}}samples.Sort();return new{label,samples=samples.Count,averageFps=1000/samples.Average(),medianMs=samples[samples.Count/2],p95Ms=samples[(int)((samples.Count-1)*.95)],drawCalls=UnityStats.drawCalls,triangles=UnityStats.triangles};}
public static async Task<string> Run(){Application.runInBackground=true;var s=TrainingSession.Instance;var p=s.player;var v=p.view;var local=v.localPosition;var rotation=v.localRotation;var data=new List<object>();s.MainMenu();s.ChooseMode(TrainingMode.FireExtinguisher);s.StartSimulation();data.Add(await Sample("Main classroom with fire and NPC evacuation"));p.enabled=false;v.position=new Vector3(29,2.5f,-.2f);v.LookAt(new Vector3(3.5f,3.3f,-.2f));await Task.Delay(350);data.Add(await Sample("Two-storey facade, trees, courtyard and assembled NPCs"));v.localPosition=local;v.localRotation=rotation;p.enabled=true;s.MainMenu();var settings=UnityEngine.Object.FindAnyObjectByType<TrainingSettings>();var report=new{scope="Two ten-second Editor Game view samples, not standalone performance certification",gpu=SystemInfo.graphicsDeviceName,width=Screen.width,height=Screen.height,qualityIndex=settings.Current.quality,samples=data};var json=Newtonsoft.Json.JsonConvert.SerializeObject(report,Newtonsoft.Json.Formatting.Indented);File.WriteAllText("../Documentation/CampusEditorPerformance.json",json);return json;}}
